/* O que mudou na lei: as leis e emendas de 2024 a 2026 que mudaram o que o app ensina (js/20-mudancas.js).
   Datas e ementas oficiais: Senado Federal, Dados Abertos (Legislação Federal). O que mudou: resumo das apostilas do app.
   Campos: id; n (número); nome; data (assinatura); area (matérias da OAB, a 1ª dá a cor); mud (o que mudou);
   aa (antes e agora); vig (vigência e avisos); top (a revisão geral manda revisar primeiro); ementa (oficial);
   temas ([disciplina, nº do tema, título] onde a mudança está explicada); q (questões que citam a lei);
   em (quando entrou no app: o que for mais novo que a última visita aparece como novidade). */
window.MUDANCAS=[
 {"id":"ec141","n":"EC 141/2026","nome":"Jornada de 40 horas e 2 dias de repouso","data":"2026-10-16","area":["trab"],"mud":["A jornada constitucional passa a **8 horas diárias e 40 semanais**, aos poucos: **42 horas** a partir de dezembro de 2026 e **40 horas** a partir de dezembro de 2027 (art. 7º, XIII, e art. 6º da EC).","O **repouso semanal** passa a **2 dias**, um deles preferencialmente aos domingos, 2 meses após a publicação (art. 7º, XV).","Tudo **sem redução de salário**, nem dos pisos, e vale também para o **empregado doméstico**.","Norma coletiva pode criar regime compensatório com **média** de 2 dias de repouso semanal **dentro do mês**, com pelo menos 1 dia de folga em cada semana (art. 7º, §2º).","Ao empregado com **diploma de nível superior** que ganha pelo menos **2,5 vezes o teto do RGPS** não se aplicam as regras de duração e controle de jornada, mas continuam os 2 dias de repouso."],"aa":[["Limite semanal","44 horas","40 horas (42 em dez/2026 e 40 em dez/2027)"],["Repouso semanal remunerado","24 horas consecutivas","2 dias"]],"vig":"Publicada em 16/10/2026: 42 horas e 2 dias de repouso a partir de dezembro de 2026; 40 horas a partir de dezembro de 2027.","top":1,"ementa":"Altera o art. 7º da Constituição Federal para reduzir a duração máxima semanal do trabalho e prever 2 (dois) dias de repouso semanal remunerado, sem qualquer redução salarial.","temas":[["trab",5,"Jornada de trabalho"],["trab",3,"A relação de emprego"]],"q":["tb02","zb04","zb05"],"em":"2026-11-01"},
 {"id":"ec140","n":"EC 140/2026","nome":"Aposentadoria especial dos agentes de saúde","data":"2026-10-16","area":["prev"],"mud":["Os **agentes comunitários de saúde** e os **de combate às endemias** se aposentam com **57 anos** (mulher) e **60** (homem), com pelo menos **25 anos** de contribuição e de efetivo exercício na atividade (arts. 40 e 201, §8º-A, da Constituição).","A atuação deles é **essencial ao SUS e exclusiva de Estado**, e ficam vedadas a contratação temporária e a terceirizada, salvo emergência em saúde pública (art. 198)."],"ementa":"Altera os arts. 40, 198 e 201 da Constituição Federal, para estabelecer o direito à aposentadoria diferenciada aos agentes comunitários de saúde e aos agentes de combate às endemias, bem como para determinar a regularização do vínculo funcional desses agentes; e dá outras providências.","temas":[["prev",5,"Aposentadorias"]],"em":"2026-11-01"},
 {"id":"l15511","n":"Lei 15.511/2026","nome":"Nova Diretoria do Conselho Federal da OAB","data":"2026-09-21","area":["etica"],"mud":["A **Diretoria do Conselho Federal** passou a ter **7 membros**: Presidente, Vice-Presidente, Secretário-Geral, **Corregedor-Geral**, Diretor Tesoureiro, **Diretor Administrativo** e **Diretor Executivo** (art. 55 do Estatuto).","Os **Conselhos Seccionais** podem criar diretorias regimentais temporárias."],"ementa":"Altera a Lei nº 8.906, de 4 de julho de 1994 (Estatuto da Advocacia), para modificar a nomenclatura do Secretário-Geral Adjunto, bem como a composição da Diretoria do Conselho Federal da Ordem dos Advogados do Brasil, e facultar aos Conselhos Seccionais a criação de diretorias regimentais temporárias.","temas":[["etica",13,"A Ordem dos Advogados do Brasil"]],"q":["zf02"],"em":"2026-11-01"},
 {"id":"lc236","n":"LC 236/2026","nome":"Arbitragem, mediação e teto das multas tributárias","data":"2026-09-04","area":["trib"],"mud":["Reformou o CTN com normas gerais de **solução consensual de conflitos** e de **processo administrativo fiscal**: arbitragem tributária, mediação e programas de conformidade.","**Suspendem** a exigibilidade: a arbitragem, a proposta de transação aceita, o acordo de mediação e o seguro garantia ou a fiança aceitos na execução fiscal (art. 151). **Extinguem** o crédito: a sentença arbitral favorável ao contribuinte e o cumprimento do acordo de mediação (art. 156).","**Multa** proporcional limitada a **75%** do tributo; **100%** em fraude, sonegação ou conluio; **150%** na reincidência (art. 113-A).","Novas causas de **interrupção da prescrição**, como a mediação e a arbitragem (art. 174, §1º), e, havendo **pagamento parcial**, a decadência conta do **fato gerador** (art. 150, §6º)."],"vig":"Em vigor desde 4/9/2026. Estados, DF e Municípios têm 2 anos para adaptar suas leis (art. 211-A do CTN).","ementa":"Altera a Lei nº 5.172, de 25 de outubro de 1966 (Código Tributário Nacional), para dispor sobre normas gerais para solução de controvérsias, consensualidade e processo administrativo em matéria tributária e aduaneira, e revoga dispositivo da Lei nº 9.430, de 27 de dezembro de 1996.","temas":[["trib",7,"Crédito tributário"]],"q":["tr06","xt10","zt01","zt02","zt03"],"em":"2026-11-01"},
 {"id":"l15487","n":"Lei 15.487/2026","nome":"Violência sexual contra crianças, inclusive por IA","data":"2026-08-06","area":["eca","penal","pp"],"mud":["Os crimes do ECA passaram a falar em **conteúdo de violência sexual contra criança ou adolescente**, real ou fictício, inclusive o gerado por **inteligência artificial** (art. 241-E).","Produzir, vender ou divulgar esse conteúdo: **4 a 10 anos**; adquirir ou armazenar: **3 a 6 anos**; **simular** por montagem ou IA: **3 a 5 anos**; **aliciamento on-line** de menor de 14: 3 a 5 anos, com aumento se usar deepfake ou perfil falso.","Cabe **prisão preventiva** nesses crimes e nos crimes sexuais contra criança ou adolescente (art. 313, VI, do CPP).","Aos condenados por exploração sexual e pornografia infantil do ECA, a perda do cargo e a incapacidade para o poder familiar passaram a ser **automáticas** (art. 92, §2º, do CP)."],"ementa":"Institui medidas de enfrentamento e repressão ao crime de violência sexual contra criança ou adolescente, inclusive no ambiente digital e com uso de inteligência artificial; e altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), o Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), a Lei nº 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente), a Lei nº 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos), e a Lei nº 12.850, de 2 de agosto de 2013 (Lei de Combate ao Crime Organizado), para recrudescer o tratamento penal aos criminosos sexuais.","temas":[["eca",10,"Crimes e infrações administrativas"],["pen2",9,"Efeitos da condenação e reabilitação"],["pp2",1,"Prisões e medidas cautelares"]],"q":["zc02","zc03"],"em":"2026-11-01"},
 {"id":"l15484","n":"Lei 15.484/2026","nome":"Recurso especial passa a exigir relevância","data":"2026-08-04","area":["pc"],"mud":["Regulamentou o filtro da **relevância da questão federal** no **recurso especial** (EC 125/2022), no art. 1.035-A do CPC, para recursos **interpostos a partir de 3/9/2026**.","O STJ só recusa o recurso por falta de relevância com **2/3** dos membros do órgão competente.","Há **relevância presumida** em ações penais, de improbidade, de valor acima de 500 salários mínimos, que possam gerar inelegibilidade e quando o acórdão contraria jurisprudência dominante do STJ.","Os acórdãos do regime de relevância entraram nos precedentes do **art. 927** do CPC."],"ementa":"Regulamenta o regime de relevância das questões de direito federal infraconstitucional para admissão dos recursos especiais no Superior Tribunal de Justiça e altera a Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil).","temas":[["pc2",5,"Recursos aos tribunais superiores"],["pc2",6,"Técnicas de julgamento e precedentes"],["prc",6,"Os recursos na prática"]],"em":"2026-11-01"},
 {"id":"l15472","n":"Lei 15.472/2026","nome":"Honorários têm natureza alimentar","data":"2026-07-21","area":["etica"],"mud":["Os honorários **convencionados, fixados ou arbitrados judicialmente ou de sucumbência** são direito do advogado, têm **natureza alimentar** e os **mesmos privilégios dos créditos trabalhistas** (art. 22, §9º, do Estatuto).","São **crédito privilegiado** na falência, na recuperação judicial e extrajudicial, no concurso de credores, na insolvência civil e na liquidação extrajudicial (art. 24)."],"top":1,"ementa":"Altera a Lei nº 8.906, de 4 de julho de 1994 (Estatuto da Advocacia e da Ordem dos Advogados do Brasil), a fim de explicitar a natureza alimentar dos honorários advocatícios.","temas":[["etica",8,"Honorários advocatícios"]],"q":["xe24"],"em":"2026-11-01"},
 {"id":"l15455","n":"Lei 15.455/2026","nome":"Proteção a resgatados do trabalho escravo","data":"2026-07-01","area":["penal","trab"],"mud":["Criou medidas de **proteção e acolhimento** de trabalhadores resgatados de condição análoga à de escravo e reforçou a proteção no ambiente doméstico.","Na **lesão corporal em violência doméstica** (art. 129, §9º, do CP), passou a constar a vítima com quem o agente tem **relação de trabalho doméstico**."],"ementa":"Estabelece medidas de proteção e acolhimento de trabalhadoras e trabalhadores resgatados de condição análoga à de escravo; vincula o poder público e os empregadores à obrigação de efetivar a proteção de trabalhadores no ambiente doméstico; e altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), as Leis nºs 7.998, de 11 de janeiro de 1990, 10.593, de 6 de dezembro de 2002, e 11.340, de 7 de agosto de 2006 (Lei Maria da Penha), e a Lei Complementar nº 150, de 1º de junho de 2015, para incluir disposições referentes ao combate ao trabalho em condição análoga à de escravo.","temas":[["pen3",3,"Lesões corporais (art. 129)"]],"em":"2026-11-01"},
 {"id":"l15438","n":"Lei 15.438/2026","nome":"12 meses para representar na violência doméstica","data":"2026-06-18","area":["pp","penal"],"mud":["Nos crimes de **violência doméstica e familiar contra a mulher**, a ofendida tem **12 meses**, e não 6, para oferecer **queixa ou representação**, contados do dia em que soube quem é o autor (art. 16-A da Lei Maria da Penha e art. 103, parágrafo único, do CP)."],"aa":[["Decadência na violência doméstica","6 meses","12 meses"]],"ementa":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), a Lei nº 11.340, de 7 de agosto de 2006 (Lei Maria da Penha), e o Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), para aumentar o prazo decadencial do direito de queixa ou de representação quando se tratar de crime praticado no âmbito de violência doméstica e familiar contra a mulher.","temas":[["pp1",4,"Ação penal"],["pen2",11,"Extinção da punibilidade"],["prp",10,"Queixa-crime e ação penal privada"],["pen3",11,"Associação criminosa e leis especiais"]],"q":["zp11"],"em":"2026-11-01"},
 {"id":"l15410","n":"Lei 15.410/2026","nome":"Tortura contra a mulher na violência doméstica","data":"2026-05-20","area":["penal"],"mud":["Submeter mulher, **de forma reiterada**, a **intenso sofrimento físico ou mental** no contexto de violência doméstica e familiar passou a ser **tortura** (art. 1º, III, da Lei 9.455/1997).","A lei também reforçou, na LEP, a proteção da mulher contra novas ameaças de agressores condenados ou presos provisoriamente."],"ementa":"Altera a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), para estabelecer medidas destinadas a reforçar a proteção da mulher vítima de violência doméstica e familiar, especialmente contra a reiteração de ameaça ou de violência perpetrada por agressores condenados ou submetidos a prisão provisória; e a Lei nº 9.455, de 7 de abril de 1997 (Lei dos Crimes de Tortura), para prever como modalidade de tortura a submissão reiterada da mulher a intenso sofrimento físico ou mental, no contexto de violência doméstica e familiar.","temas":[["pen3",11,"Associação criminosa e leis especiais"]],"em":"2026-11-01"},
 {"id":"l15402","n":"Lei 15.402/2026","nome":"Progressão volta a 1/6 nos crimes comuns","data":"2026-05-08","area":["penal"],"mud":["Devolveu ao caput do art. 112 da LEP a fração de **1/6** para o **primário em crime sem violência ou grave ameaça**. O reincidente nesses crimes cumpre **20%**; com violência ou grave ameaça, **25%** (primário) e **30%** (reincidente).","Como 1/6 é um pouco mais que 16%, o primário que praticou o crime **antes de 8/5/2026** continua com os **16%** do Pacote Anticrime, mais favoráveis.","**Crimes contra o Estado Democrático de Direito**: ficaram fora dos incisos I e II (o primário progride com 1/6, mesmo com violência); no mesmo contexto, aplica-se o **concurso formal próprio**; em **contexto de multidão**, a pena é reduzida de 1/3 a 2/3 para quem não financiou nem liderou."],"aa":[["Primário, crime sem violência","16%","1/6 (fatos a partir de 8/5/2026)"]],"vig":"Em vigor desde 8/5/2026.","ementa":"Altera a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal) e o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal).","temas":[["pen2",8,"Execução: progressão, remição e detração"],["pen3",11,"Associação criminosa e leis especiais"]],"q":["p207","zp10"],"em":"2026-11-01"},
 {"id":"ec139","n":"EC 139/2026","nome":"Tribunais de Contas permanentes","data":"2026-05-05","area":["fin","const"],"mud":["Os **Tribunais de Contas** passaram a ser **instituições permanentes e essenciais** ao controle externo (art. 75 da Constituição).","É **vedada a extinção, a criação ou a instalação** de tribunais e conselhos de contas **dos Municípios**: os que existem permanecem, e não se criam novos (art. 31, §1º)."],"ementa":"Altera o § 1º do art. 31 e o art. 75 da Constituição Federal para estabelecer os Tribunais de Contas como órgãos permanentes e essenciais ao controle externo da administração pública.","temas":[["fin",9,"Fiscalização e controle"]],"em":"2026-11-01"},
 {"id":"l15397","n":"Lei 15.397/2026","nome":"Furto, roubo, receptação e estelionato mais duros","data":"2026-04-30","area":["penal","pp"],"mud":["**Furto simples**: 1 a 6 anos. Furto de **celular, computador**, por **fraude eletrônica**, de veículo levado para outro Estado, de gado, arma ou explosivo: 4 a 10 anos. O **repouso noturno** aumenta a pena de **metade**.","**Roubo**: 6 a 10 anos, com aumento se o bem é celular, computador ou arma de fogo. **Latrocínio**: 24 a 30 anos. O aumento da pena do roubo com lesão grave foi **vetado**.","**Receptação**: 2 a 6 anos; **receptação de animal**: 3 a 8 anos.","**Estelionato**: a ação penal voltou a ser **pública incondicionada** (revogado o §5º do art. 171), e ceder **conta bancária para o crime** (a \"conta laranja\") passou a ser estelionato (inciso VII)."],"aa":[["Furto simples","1 a 4 anos","1 a 6 anos"],["Roubo","4 a 10 anos","6 a 10 anos"],["Latrocínio","20 a 30 anos","24 a 30 anos"],["Receptação","1 a 4 anos","2 a 6 anos"],["Repouso noturno no furto","aumento de 1/3","aumento de metade"],["Ação penal no estelionato","pública condicionada à representação","pública incondicionada"]],"vig":"Em vigor desde maio de 2026. As penas maiores não alcançam fatos anteriores, porque a lei penal mais grave não retroage.","top":1,"ementa":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), a fim de majorar as penas previstas para os crimes de furto, roubo, estelionato, receptação, receptação de animal e interrupção ou perturbação de serviço telegráfico, telefônico, informático, telemático ou de informação de utilidade pública, bem como para tipificar os crimes de receptação de animal doméstico e de fraude bancária.","temas":[["pen3",7,"Crimes contra o patrimônio"],["pp1",4,"Ação penal"],["pp1",1,"O processo penal e a Constituição"],["pen2",3,"A dosimetria: o cálculo da pena"],["pen2",12,"Prescrição penal"],["pp2",3,"Procedimentos"],["prp",4,"As prisões e a liberdade"]],"q":["pe27","p312","zp09"],"em":"2026-11-01"},
 {"id":"lc230","n":"LC 230/2026","nome":"Desmembramento de Município para incorporação a outro","data":"2026-04-15","area":["const"],"mud":["Regulamentou o art. 18, §4º, da Constituição **só** para o **desmembramento de parte de um Município para incorporação a outro, limítrofe**: prazo de **15 anos** a partir de abril de 2026, iniciativa da Assembleia Legislativa e **plebiscito único** nos dois Municípios.","Em nenhuma hipótese o desmembramento pode **criar novo Município**. A criação de Municípios continua sem a lei complementar exigida."],"ementa":"Dispõe sobre normas gerais aplicáveis ao desmembramento de parte de um Município para incorporação a outro, limítrofe, nos termos do § 4º do art. 18 da Constituição Federal.","temas":[["con2",2,"A Federação brasileira"]],"em":"2026-11-01"},
 {"id":"l15384","n":"Lei 15.384/2026","nome":"Violência vicária e vicaricídio","data":"2026-04-09","area":["penal"],"mud":["A **violência vicária**, praticada contra filhos, pais, dependentes, parentes ou a rede de apoio da mulher para atingi-la, entrou entre as formas de violência doméstica (art. 7º, VI, da Lei Maria da Penha).","Criou o **vicaricídio** (art. 121-B do CP): matar descendente, ascendente, dependente, enteado ou pessoa sob guarda da mulher para lhe causar sofrimento, punição ou controle, no contexto de violência doméstica. Reclusão de **20 a 40 anos**; é crime **hediondo**."],"ementa":"Altera as Leis nºs 11.340, de 7 de agosto de 2006 (Lei Maria da Penha), e 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos), e o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para prever a violência vicária entre as formas de violência doméstica e familiar e criar qualificadora do crime de homicídio e incluí-la no rol dos crimes hediondos.","temas":[["pen3",2,"Crimes contra a vida"],["pen3",11,"Associação criminosa e leis especiais"]],"q":["zp01"],"em":"2026-11-01"},
 {"id":"l15383","n":"Lei 15.383/2026","nome":"Tornozeleira com alerta à vítima","data":"2026-04-09","area":["penal"],"mud":["A **monitoração eletrônica** do agressor virou medida protetiva **autônoma**, com aplicativo ou dispositivo que **alerta a vítima** quando ele se aproxima (arts. 12-D e 22, VIII, da Lei Maria da Penha).","Ela tem **prioridade** quando há descumprimento de medidas anteriores ou risco iminente, e o juiz que deixar de aplicá-la deve fundamentar.","No **descumprimento de medida protetiva**, a pena aumenta de **1/3 até a metade** se o agressor viola as áreas de exclusão ou remove ou altera a tornozeleira (art. 24-A, §4º)."],"ementa":"Altera as Leis nºs 11.340, de 7 de agosto de 2006 (Lei Maria da Penha), 13.756, de 12 de dezembro de 2018, e 14.899, de 17 de junho de 2024, para estabelecer a monitoração eletrônica de agressores como medida protetiva autônoma e os critérios de prioridade para a monitoração eletrônica de agressores, prever causa de aumento de pena no crime de descumprimento de medida protetiva e dispor sobre campanhas e diretrizes orçamentárias.","temas":[["pen3",11,"Associação criminosa e leis especiais"]],"em":"2026-11-01"},
 {"id":"l15380","n":"Lei 15.380/2026","nome":"Retratação na Maria da Penha só se a vítima pedir","data":"2026-04-06","area":["penal","pp"],"mud":["A audiência do art. 16 da Lei Maria da Penha serve para **confirmar a retratação**, e não a representação, e só é marcada se a vítima **manifestar expressamente** que quer se retratar, antes do recebimento da denúncia."],"ementa":"Altera a Lei nº 11.340, de 7 de agosto de 2006 (Lei Maria da Penha), para estabelecer que a audiência de retratação nos casos de violência doméstica e familiar contra a mulher somente seja realizada mediante manifestação expressa da vítima, apresentada antes do recebimento da denúncia.","temas":[["pen3",11,"Associação criminosa e leis especiais"]],"em":"2026-11-01"},
 {"id":"l15377","n":"Lei 15.377/2026","nome":"Exames preventivos de câncer e vacinação","data":"2026-04-02","area":["trab"],"mud":["O empregado pode faltar até **3 dias a cada 12 meses** para **exames preventivos de câncer**, e agora o empregador deve **informá-lo** dessa possibilidade, inclusive para exames de **HPV** (art. 473, §3º, e art. 169-A da CLT).","As empresas também devem divulgar informações sobre **campanhas oficiais de vacinação** e sobre os cânceres de mama, de colo do útero e de próstata."],"ementa":"Altera a Consolidação das Leis do Trabalho (CLT), aprovada pelo Decreto-Lei nº 5.452, de 1º de maio de 1943, para determinar que as empresas disponibilizem a seus empregados informações sobre campanhas oficiais de vacinação, sobre o papilomavírus humano (HPV) e sobre os cânceres de mama, de colo do útero e de próstata.","temas":[["trab",8,"Interrupção e suspensão do contrato"]],"em":"2026-11-01"},
 {"id":"l15371","n":"Lei 15.371/2026","nome":"Licença-paternidade maior e salário-paternidade","data":"2026-03-31","area":["trab","prev"],"mud":["Criou o **salário-paternidade**, pago pela Previdência Social (para o empregado, a empresa paga e é reembolsada).","A licença passa a **10 dias em 2027**, **15 em 2028** e **20 em 2029** (este último depende de meta fiscal), com acréscimo de **1/3** se a criança tiver deficiência.","O pai tem **estabilidade** desde o início da licença até **1 mês** após o fim, e deve avisar o empregador com **30 dias** de antecedência.","Se a mãe não constar do registro, ou se a adoção ou guarda for só do pai, a licença-paternidade **equivale à licença-maternidade**."],"aa":[["Licença-paternidade","5 dias","10 dias em 2027, 15 em 2028 e 20 em 2029"]],"vig":"Começa a valer em 1º de janeiro de 2027; até lá, continuam os 5 dias. O edital do Exame de Ordem costuma excluir leis que entram em vigor depois da sua publicação.","ementa":"Dispõe sobre a licença-paternidade; institui o salário-paternidade no âmbito da Previdência Social; e altera a Consolidação das Leis do Trabalho, aprovada pelo Decreto-Lei nº 5.452, de 1º de maio de 1943, e as Leis nºs 8.212, de 24 de julho de 1991 (Lei Orgânica da Seguridade Social), 8.213, de 24 de julho de 1991, e 11.770, de 9 de setembro de 2008.","temas":[["trab",9,"Proteção à maternidade, à paternidade e ao trabalho do menor"]],"q":["zb10"],"em":"2026-11-01"},
 {"id":"l15358","n":"Lei 15.358/2026","nome":"Marco Legal do Combate ao Crime Organizado","data":"2026-03-24","area":["penal","pp"],"mud":["Criou os crimes de **domínio social estruturado** e de favorecimento a ele, e penas próprias para crimes de **organização criminosa ultraviolenta, grupo paramilitar ou milícia privada**: homicídio de **20 a 40 anos**, roubo e extorsão com pena **em triplo**, furto de 4 a 10 anos e a nova **ameaça** do art. 147-C.","**Progressão** nos crimes hediondos: **70%** (primário), **75%** (com resultado morte e outros casos), **80%** (reincidente) e **85%** (reincidente com morte) (art. 112 da LEP).","**Livramento condicional** vedado também ao comando de organização criminosa ultraviolenta e aos crimes de domínio social estruturado.","**Audiência de custódia** em até 24 horas **por videoconferência**, com entrevista reservada com o defensor; presencial, só por força maior (art. 310 do CPP).","O RESE contra decisões sobre fiança, preventiva, liberdade provisória e relaxamento pode ganhar **efeito suspensivo ou ativo** no tribunal.","Na regra de conexão em que prevalece o **júri** (art. 78, I, do CPP), a lei ressalvou os homicídios cometidos por membros dessas organizações. A ressalva é questionada no STF."],"aa":[["Progressão: primário em hediondo","40%","70%"],["Progressão: reincidente em hediondo com morte","70%","85%"]],"vig":"Em vigor desde 25/3/2026. As regras mais graves valem só para fatos a partir dessa data.","top":1,"ementa":"Institui o Marco Legal do Combate ao Crime Organizado no Brasil (Lei Raul Jungmann); tipifica os crimes de domínio social estruturado e de favorecimento ao domínio social estruturado; e altera os Decretos-Leis nºs 2.848, de 7 de dezembro de 1940 (Código Penal), e 3.689, de 3 de outubro de 1941 (Código de Processo Penal), e as Leis nºs 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos), 7.210, de 11 de julho de 1984 (Lei de Execução Penal), 11.343, de 23 de agosto de 2006, 10.826, de 22 de dezembro de 2003, 9.613, de 3 de março de 1998, 4.737, de 15 de julho de 1965 (Código Eleitoral); 13.756, de 12 de dezembro de 2018; e 14.790, de 29 de dezembro de 2023.","temas":[["pen2",8,"Execução: progressão, remição e detração"],["pen3",7,"Crimes contra o patrimônio"],["pen3",2,"Crimes contra a vida"],["pp2",1,"Prisões e medidas cautelares"],["pen2",7,"Suspensão condicional da pena e livramento condicional"],["pen2",9,"Efeitos da condenação e reabilitação"],["pen3",3,"Lesões corporais (art. 129)"],["pen3",6,"Crimes contra a liberdade individual"],["pen3",11,"Associação criminosa e leis especiais"],["pp1",5,"Competência"],["pp2",7,"Recursos no processo penal"],["prp",4,"As prisões e a liberdade"]],"q":["pe20","p237","zp08","zq02","zr01"],"em":"2026-11-01"},
 {"id":"l15355","n":"Lei 15.355/2026","nome":"Desastre ambiental que fere animais","data":"2026-03-11","area":["amb"],"mud":["Responde pelas penas de **maus-tratos a animais** quem provoca **desastre ambiental** que prejudique a vida, a integridade ou o bem-estar de animais silvestres ou domésticos (art. 32, §1º-C, da Lei 9.605/1998).","A lei também criou a **Política de Acolhimento e Manejo de Animais Resgatados (Amar)**."],"ementa":"Institui a Política de Acolhimento e Manejo de Animais Resgatados (Amar); e altera as Leis nºs 9.605, de 12 de fevereiro de 1998, 12.334, de 20 de setembro de 2010, e 12.340, de 1º de dezembro de 2010.","temas":[["amb",5,"Responsabilidade ambiental"]],"em":"2026-11-01"},
 {"id":"l15353","n":"Lei 15.353/2026","nome":"Estupro de vulnerável: presunção absoluta","data":"2026-03-08","area":["penal"],"mud":["É **absoluta** a presunção de vulnerabilidade da vítima do estupro de vulnerável, e é inadmissível sua relativização (art. 217-A, §4º-A, do CP).","As penas valem **independentemente** do consentimento da vítima, de sua experiência sexual, de relações anteriores ou de **gravidez** resultante do crime (§5º). A lei pôs no Código o que já dizia a Súmula 593 do STJ."],"ementa":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para prever a presunção absoluta de vulnerabilidade da vítima do crime de estupro de vulnerável e para estabelecer a aplicação das penas desse crime independentemente da experiência sexual da vítima ou da ocorrência de gravidez resultante do estupro.","temas":[["pen3",8,"Crimes contra a dignidade sexual"]],"q":["zp06"],"em":"2026-11-01"},
 {"id":"lc227","n":"LC 227/2026","nome":"ITBI pelo valor de mercado e Comitê Gestor do IBS","data":"2026-01-13","area":["trib"],"mud":["Criou o **Comitê Gestor do IBS**, regulou o processo administrativo do IBS e trouxe normas gerais do **ITCMD**.","**ITBI**: valor venal é o valor pelo qual o bem seria negociado **à vista, em condições normais de mercado**, estimado por critérios técnicos (art. 38 do CTN). Os primeiros julgados depois da lei mantiveram as garantias do Tema 1.113 do STJ: o valor de referência do Município serve para fiscalizar, mas não substitui automaticamente a declaração do contribuinte.","A contribuição de **iluminação pública** ganhou norma geral (art. 82-A do CTN), que permite a cobrança na **fatura de energia**."],"ementa":"Institui o Comitê Gestor do Imposto sobre Bens e Serviços (CGIBS); dispõe sobre o processo administrativo tributário do Imposto sobre Bens e Serviços (IBS) e sobre a distribuição do produto da arrecadação do IBS aos entes federativos; institui normais gerais relativas ao Imposto sobre Transmissão Causa mortis e Doação de Quaisquer Bens ou Direitos (ITCMD); altera a Lei nº 5.172, de 25 de outubro de 1966 (Código Tributário Nacional), a Lei nº 1.079, de 10 de abril de 1950, a Lei nº 9.430, de 27 de dezembro de 1996, a Lei nº 10.893, de 13 julho de 2004, a Lei nº 14.113, de 25 de dezembro de 2020, a Lei Complementar nº 63, de 11 de janeiro de 1990, a Lei Complementar nº 87, de 13 de setembro de 1996 (Lei Kandir), a Lei Complementar nº 123, de 14 de dezembro de 2006, a Lei Complementar nº 141, de 13 de janeiro de 2012, a Lei Complementar nº 192, de 11 de março de 2022, a Lei Complementar nº 214, de 16 de janeiro de 2025, o Decreto-Lei nº 37, de 18 de novembro de 1966, e o Decreto nº 70.235, de 6 de março de 1972; e revoga dispositivos da Lei nº 10.833, de 29 de dezembro de 2003, e da Medida Provisória nº 2.158-35, de 24 de agosto de 2001.","temas":[["trib",3,"Competência tributária"],["trib",2,"Espécies tributárias"]],"q":["zt04"],"em":"2026-11-01"},
 {"id":"lc225","n":"LC 225/2026","nome":"Código de Defesa do Contribuinte e o devedor contumaz","data":"2026-01-08","area":["trib","penal"],"mud":["Instituiu o **Código de Defesa do Contribuinte**.","Na **apropriação indébita previdenciária** (art. 168-A do CP), pagar antes da ação fiscal **não extingue a punibilidade** do agente declarado **devedor contumaz** em decisão administrativa definitiva e inscrito no Cadin (§5º), mesmo que depois ele deixe de sê-lo, quanto aos atos daquele período (§6º)."],"ementa":"Institui o Código de Defesa do Contribuinte.","temas":[["pen3",7,"Crimes contra o patrimônio"]],"em":"2026-11-01"},
 {"id":"l15300","n":"Lei 15.300/2025","nome":"Licença Ambiental Especial para obras estratégicas","data":"2025-12-22","area":["amb"],"mud":["A **Licença Ambiental Especial (LAE)**, criada pela MP 1.308/2025, virou lei. Vale para atividades e empreendimentos **estratégicos**, definidos em decreto, mesmo que possam causar **significativa degradação**.","Mesmo assim, exige **EIA/RIMA** e **audiência pública obrigatória**, e o processo deve terminar em até **12 meses**."],"ementa":"Dispõe sobre o licenciamento ambiental especial, para a consecução eficiente e eficaz de atividades e de empreendimentos estratégicos, nos termos que especifica; e altera as Leis nºs 15.190, de 8 de agosto de 2025, e 13.116, de 20 de abril de 2015.","temas":[["amb",4,"Política Nacional do Meio Ambiente (Lei 6.938/1981)"]],"em":"2026-11-01"},
 {"id":"l15299","n":"Lei 15.299/2025","nome":"Corte de árvore por risco de acidente","data":"2025-12-22","area":["amb"],"mud":["Não há o crime do art. 49 da Lei 9.605/1998 quando a **poda ou o corte** da árvore é feito por **risco de acidente**, depois de pedido ao órgão ambiental que ficou **45 dias sem resposta fundamentada** (autorização tácita, §2º).","A lei permite contratar **profissional habilitado** para fazer o serviço."],"ementa":"Altera a Lei nº 9.605, de 12 de fevereiro de 1998 (Lei de Crimes Ambientais), para estabelecer que não configura crime a poda ou o corte de árvore em logradouros públicos ou em propriedades privadas no caso de não atendimento pelo órgão ambiental do pedido de supressão feito em razão da possibilidade de ocorrência de acidente, e permite a contratação de profissional habilitado para a execução do serviço de poda ou de corte de árvore.","temas":[["amb",5,"Responsabilidade ambiental"]],"em":"2026-11-01"},
 {"id":"ec138","n":"EC 138/2025","nome":"Professor pode acumular com cargo de qualquer natureza","data":"2025-12-19","area":["adm","const"],"mud":["Havendo compatibilidade de horários, é permitido acumular **um cargo de professor com outro de qualquer natureza** (art. 37, XVI, b, da Constituição)."],"aa":[["Professor com outro cargo","só cargo técnico ou científico","cargo de qualquer natureza"]],"ementa":"Altera o art. 37 da Constituição Federal para permitir a acumulação remunerada de um cargo de professor com outro de qualquer natureza.","temas":[["adm",6,"Agentes públicos"]],"q":["ad18"],"em":"2026-11-01"},
 {"id":"ec137","n":"EC 137/2025","nome":"Sem IPVA para carros com 20 anos ou mais","data":"2025-12-09","area":["trib"],"mud":["O IPVA **não incide** sobre veículos terrestres de passageiros, caminhonetes e mistos com **20 anos ou mais de fabricação**, salvo micro-ônibus, ônibus, reboques e semirreboques (art. 155, §6º, III, e, da Constituição)."],"ementa":"Altera o art. 155 da Constituição Federal para conceder imunidade do Imposto sobre a Propriedade de Veículos Automotores (IPVA) aos veículos que especifica.","temas":[["trib",3,"Competência tributária"]],"em":"2026-11-01"},
 {"id":"l15280","n":"Lei 15.280/2025","nome":"Penas maiores nos crimes sexuais contra vulnerável","data":"2025-12-05","area":["penal","pp"],"mud":["**Estupro de vulnerável** (art. 217-A): reclusão de **10 a 18 anos**; 12 a 24 se resulta lesão grave; 20 a 40 se resulta morte.","Também subiram as penas da **corrupção de menores** (art. 218, 6 a 14 anos), da **lascívia na presença de menor de 14** (art. 218-A, 5 a 12 anos) e da **exploração sexual de vulnerável** (art. 218-B, 7 a 16 anos).","O CPP ganhou **medidas protetivas de urgência** para vítimas de crimes contra a dignidade sexual, homem ou mulher, nos moldes da Lei Maria da Penha.","Descumprir medida protetiva passou a ser crime também no **art. 338-A do CP**, com a mesma pena da Lei Maria da Penha."],"aa":[["Estupro de vulnerável","8 a 15 anos","10 a 18 anos"]],"ementa":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para agravar a pena dos crimes contra a dignidade sexual de pessoa vulnerável; o Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), para prever medidas protetivas de urgência a vítimas de crimes contra a dignidade sexual e em situação de especial vulnerabilidade; a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), para prever a monitoração eletrônica dos condenados por crime contra a dignidade sexual; a Lei nº 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente), para estabelecer mecanismos de proteção a crianças e a adolescentes vítimas de crimes contra a dignidade sexual; e a Lei nº 13.146, de 6 de julho de 2015 (Estatuto da Pessoa com Deficiência), para assegurar assistência psicológica e social especializada às pessoas com deficiência vítimas de crimes contra a dignidade sexual e a suas famílias.","temas":[["pen3",8,"Crimes contra a dignidade sexual"],["pp2",1,"Prisões e medidas cautelares"],["pen3",11,"Associação criminosa e leis especiais"]],"q":["zp06","zr05"],"em":"2026-11-01"},
 {"id":"l15272","n":"Lei 15.272/2025","nome":"Preventiva: periculosidade concreta e DNA do preso","data":"2025-11-26","area":["pp"],"mud":["É proibida a **preventiva baseada só na gravidade abstrata** do crime (art. 312, §4º, do CPP), e a lei listou critérios para medir a **periculosidade**, como o modo de agir e a participação em organização criminosa (§3º).","Na prisão em flagrante por crime com **violência ou grave ameaça**, contra a **dignidade sexual**, **hediondo** ou por integrante de organização criminosa armada, deve ser pedida a **coleta de material biológico** para o **perfil genético** do preso (art. 310-A)."],"ementa":"Altera o Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), para dispor sobre as circunstâncias que recomendam a conversão da prisão em flagrante em preventiva, sobre a coleta de material biológico para obtenção e armazenamento do perfil genético do custodiado e sobre os critérios para aferição da periculosidade do agente para concessão de prisão preventiva, inclusive quando da audiência de custódia.","temas":[["pp2",1,"Prisões e medidas cautelares"]],"q":["r204","zr02"],"em":"2026-11-01"},
 {"id":"l15245","n":"Lei 15.245/2025","nome":"Quem contrata crime responde por associação criminosa","data":"2025-10-29","area":["penal"],"mud":["Incorre na pena da **associação criminosa** quem, de qualquer modo, **solicita ou contrata** o cometimento de crime a integrante de associação criminosa, seja qual for a pena do crime contratado (art. 288, §2º, do CP).","A lei também criou os crimes de **obstrução de ações contra o crime organizado** e de conspiração para essa obstrução (Lei 12.850/2013)."],"ementa":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para dispor sobre o crime de associação criminosa, a Lei nº 12.694, de 24 de julho de 2012, para ampliar a proteção pessoal dos agentes públicos ou processuais envolvidos no combate ao crime organizado, e a Lei nº 12.850, de 2 de agosto de 2013, para tipificar as condutas de obstrução de ações contra o crime organizado e de conspiração para obstrução de ações contra o crime organizado.","temas":[["pen3",11,"Associação criminosa e leis especiais"]],"em":"2026-11-01"},
 {"id":"l15240","n":"Lei 15.240/2025","nome":"Abandono afetivo vira ilícito civil","data":"2025-10-28","area":["eca","civil"],"mud":["Os pais devem aos filhos **assistência afetiva**, por meio de convívio ou visitação periódica, além da assistência material (arts. 4º e 22 do ECA).","A ação ou omissão que ofende direito fundamental da criança, **incluído o abandono afetivo**, passou a ser **conduta ilícita sujeita a reparação de danos** (art. 5º, parágrafo único). Antes, o tema dependia só da jurisprudência do STJ."],"ementa":"Altera a Lei nº 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente), para caracterizar o abandono afetivo como ilícito civil.","temas":[["eca",3,"Convivência familiar e comunitária"],["eca",1,"A doutrina da proteção integral"]],"q":["zc01"],"em":"2026-11-01"},
 {"id":"l15234","n":"Lei 15.234/2025","nome":"Bebida para criança: pena maior se ela consumir","data":"2025-10-07","area":["eca"],"mud":["No crime de **vender, fornecer ou entregar bebida alcoólica** a criança ou adolescente, ou, sem justa causa, outros produtos que causem dependência (art. 243 do ECA), a pena aumenta de **1/3 até a metade** se a criança ou o adolescente **consumir** o produto."],"ementa":"Cria causa de aumento de pena para o crime de vender, fornecer, servir, ministrar ou entregar, ainda que gratuitamente, de qualquer forma, a criança ou a adolescente, bebida alcoólica ou, sem justa causa, outros produtos cujos componentes possam causar dependência física ou psíquica, no caso de a criança ou o adolescente utilizar ou consumir o produto.","temas":[["eca",10,"Crimes e infrações administrativas"]],"em":"2026-11-01"},
 {"id":"l15230","n":"Lei 15.230/2025","nome":"Quando se confere a idade mínima do candidato","data":"2025-10-02","area":["eleit"],"mud":["A idade mínima é verificada na **data da posse**, para os cargos do **Executivo**; na **data-limite do pedido de registro**, para **Vereador** (18 anos); e na **data da posse presumida**, para as demais Casas Legislativas (art. 11, §2º, da Lei 9.504/1997).","A lei também prevê **panfletos em Braille** nas campanhas dos candidatos a cargos majoritários."],"ementa":"Altera a Lei nº 9.504, de 30 de setembro de 1997 (Lei das Eleições), para disciplinar a aferição da idade de elegibilidade e para dispor sobre o uso de panfletos em sistema Braille nas campanhas eleitorais dos candidatos aos cargos majoritários.","temas":[["eleit",2,"Direitos políticos"]],"q":["el15","zl01"],"em":"2026-11-01"},
 {"id":"lc219","n":"LC 219/2025","nome":"Ficha Limpa: nova contagem da inelegibilidade","data":"2025-09-29","area":["eleit"],"mud":["O prazo de **8 anos** passou a contar, em vários casos, da **decisão** que decreta a perda do mandato, da **renúncia** ou da **condenação por órgão colegiado**. Antes, por exemplo, corria do fim do mandato ou do cumprimento da pena.","Nos crimes mais graves, como os **contra a administração pública**, continua a contagem até 8 anos após o cumprimento da pena.","Criou um **teto de 12 anos** para a soma de inelegibilidades por improbidade e passou a exigir **dolo específico** para a inelegibilidade por improbidade.","**Fatos posteriores ao registro** que afastem a inelegibilidade contam **até a diplomação** (art. 26-D da LC 64/1990)."],"vig":"Publicada em 30/9/2025 e em vigor. É questionada no STF (ADI 7.881), ainda sem decisão.","top":1,"ementa":"Altera a Lei Complementar nº 64, de 18 de maio de 1990 (Lei das Inelegibilidades), para modificar prazos de duração e de fixação dos termos iniciais e finais de contagem de inelegibilidades, e a Lei nº 9.504, de 30 de setembro de 1997 (Lei das Eleições), para prever a criação do Requerimento de Declaração de Elegibilidade (RDE).","temas":[["eleit",3,"Inelegibilidades"],["eleit",7,"O processo eleitoral"],["eleit",1,"Fontes e princípios"]],"q":["xl05"],"em":"2026-11-01"},
 {"id":"ec136","n":"EC 136/2025","nome":"Precatórios: nova data e limites de pagamento","data":"2025-09-09","area":["fin"],"mud":["Entram no orçamento seguinte os precatórios apresentados até **1º de fevereiro**, com pagamento até o fim do exercício seguinte (art. 100, §5º).","Desde agosto de 2025, a atualização é feita pelo **IPCA**, mais juros, limitada à **Selic**.","Os precatórios federais saíram do limite de despesas primárias a partir de 2026, e Estados e Municípios ganharam **limites anuais de pagamento**, conforme o estoque de precatórios em relação à receita corrente líquida."],"aa":[["Data de apresentação do precatório","2 de abril","1º de fevereiro"]],"ementa":"Altera a Constituição Federal, o Ato das Disposições Constitucionais Transitórias e a Emenda Constitucional nº 113, de 8 de dezembro de 2021, a fim de instituir limite para o pagamento de precatórios pelos Estados, pelo Distrito Federal e pelos Municípios e de estipular novo prazo de parcelamento especial de débitos dos Estados, dos Municípios e do Distrito Federal com seus regimes próprios de previdência social e dos Municípios com o Regime Geral de Previdência Social; e dá outras providências.","temas":[["fin",8,"Precatórios"]],"q":["xn10"],"em":"2026-11-01"},
 {"id":"l15190","n":"Lei 15.190/2025","nome":"Lei Geral do Licenciamento Ambiental","data":"2025-08-08","area":["amb"],"mud":["Unificou as regras do **licenciamento ambiental** no país. Além das licenças prévia, de instalação e de operação, criou modalidades simplificadas, como a **Licença por Adesão e Compromisso (LAC)**, emitida por **autodeclaração** do empreendedor.","Fazer funcionar atividade poluidora **sem licença**: detenção de **6 meses a 2 anos**, ou multa, ou ambas, até o **dobro** se o licenciamento exigir EIA (art. 60 da Lei 9.605/1998).","O crime do funcionário que concede **licença em desacordo com as normas** (art. 67) passou a exigir **dolo**: a forma culposa foi revogada."],"aa":[["Atividade sem licença (art. 60)","detenção de 1 a 6 meses, ou multa, ou ambas","detenção de 6 meses a 2 anos, ou multa, ou ambas"]],"vig":"Em vigor desde fevereiro de 2026. É questionada no STF (ADIs 7.913, 7.916 e 7.919 e ADC 102), sem decisão que a suspenda.","ementa":"Dispõe sobre o licenciamento ambiental; regulamenta o inciso IV do § 1º do art. 225 da Constituição Federal; altera as Leis nºs 9.605, de 12 de fevereiro de 1998 (Lei dos Crimes Ambientais), 9.985, de 18 de julho de 2000, e 6.938, de 31 de agosto de 1981; revoga dispositivos das Leis nºs 7.661, de 16 de maio de 1988, e 11.428, de 22 de dezembro de 2006; e dá outras providências.","temas":[["amb",4,"Política Nacional do Meio Ambiente (Lei 6.938/1981)"],["amb",5,"Responsabilidade ambiental"]],"q":["zo01"],"em":"2026-11-01"},
 {"id":"l15175","n":"Lei 15.175/2025","nome":"Transferência para acompanhar o cônjuge","data":"2025-07-23","area":["trab"],"mud":["O **empregado público** pode ser transferido para acompanhar **cônjuge ou companheiro** servidor, militar ou empregado público **deslocado no interesse da administração**, se houver filial ou representação no local. A transferência é horizontal, dentro do mesmo quadro (art. 469-A da CLT)."],"ementa":"Altera a Consolidação das Leis do Trabalho, aprovada pelo Decreto-Lei nº 5.452, de 1º de maio de 1943, para dispor sobre a transferência de empregado público cujo cônjuge ou companheiro tenha sido deslocado no interesse da administração pública.","temas":[["trab",4,"O contrato de trabalho"]],"em":"2026-11-01"},
 {"id":"l15163","n":"Lei 15.163/2025","nome":"Penas maiores para abandono de incapaz e maus-tratos","data":"2025-07-03","area":["penal","eca"],"mud":["**Abandono de incapaz** (art. 133) e **maus-tratos** (art. 136) passaram a ter as mesmas penas: reclusão de **2 a 5 anos**; de 3 a 7 se resulta lesão grave; de 8 a 14 se resulta morte.","No ECA, a **apreensão ilegal de criança ou adolescente** (art. 230) deixou de admitir a **Lei 9.099/1995** (§2º).","A lei também aumentou penas no Estatuto da Pessoa Idosa e no Estatuto da Pessoa com Deficiência."],"aa":[["Maus-tratos (art. 136)","detenção de 2 meses a 1 ano, ou multa","reclusão de 2 a 5 anos"],["Abandono de incapaz (art. 133)","detenção de 6 meses a 3 anos","reclusão de 2 a 5 anos"]],"ementa":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para modificar as penas dos crimes de abandono de incapaz e de maus-tratos, a Lei nº 10.741, de 1º de outubro de 2003 (Estatuto da Pessoa Idosa), para modificar as penas do crime de exposição a perigo da saúde e da integridade física ou psíquica da pessoa idosa, a Lei nº 13.146, de 6 de julho de 2015 (Estatuto da Pessoa com Deficiência), a fim de estabelecer penas para o crime de abandono de pessoa com deficiência que resulte em lesão corporal de natureza grave ou em morte, e a Lei nº 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente), para vedar a aplicação da Lei nº 9.099, de 26 de setembro de 1995, em caso de apreensão indevida de criança ou de adolescente.","temas":[["pen3",4,"Periclitação da vida e da saúde"],["eca",10,"Crimes e infrações administrativas"]],"q":["zp04"],"em":"2026-11-01"},
 {"id":"l15160","n":"Lei 15.160/2025","nome":"Sem redução por idade na violência sexual contra a mulher","data":"2025-07-03","area":["penal"],"mud":["A **atenuante** de ser menor de 21 anos na data do fato ou maior de 70 na data da sentença **não se aplica** quando o crime envolve **violência sexual contra a mulher** (art. 65, I, do CP).","Nesses crimes também **não há redução pela metade do prazo prescricional** por essas idades (art. 115)."],"ementa":"Modifica os arts. 65 e 115 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para alterar circunstância atenuante e vedar a redução do prazo de prescrição para os crimes que envolvam violência sexual contra a mulher, quando o agente for, na data do fato, menor de 21 (vinte e um) anos ou, na data da sentença, maior de 70 (setenta) anos de idade.","temas":[["pen2",3,"A dosimetria: o cálculo da pena"],["pen2",12,"Prescrição penal"],["prp",11,"Juizados, acordos e teses defensivas"]],"q":["pe05","p218","zq01"],"em":"2026-11-01"},
 {"id":"l15159","n":"Lei 15.159/2025","nome":"Crimes em escolas: agravante e homicídio qualificado","data":"2025-07-03","area":["penal"],"mud":["Cometer crime **nas dependências de instituição de ensino** virou **agravante genérica** (art. 61, II, m, do CP).","O **homicídio** nesse local passou a ser **qualificado** (art. 121, §2º, X), com aumento de 1/3 até a metade se a vítima tem deficiência ou doença limitante e de **2/3** se o autor é professor, funcionário ou tem autoridade sobre ela (§2º-C).","Na **lesão corporal dolosa** em escola, a pena aumenta de **1/3 a 2/3**, e de **2/3 ao dobro** nesses mesmos casos."],"ementa":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), e a Lei nº 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos), para recrudescer o tratamento penal dispensado ao autor de crime praticado nas dependências de instituição de ensino.","temas":[["pen3",2,"Crimes contra a vida"],["pen2",3,"A dosimetria: o cálculo da pena"],["pen3",3,"Lesões corporais (art. 129)"]],"q":["zp02"],"em":"2026-11-01"},
 {"id":"l15156","n":"Lei 15.156/2025","nome":"Licença maior para pais de crianças com síndrome do Zika","data":"2025-07-01","area":["trab"],"mud":["A falta justificada do pai pelo nascimento do filho (5 dias) vai a **20 dias** no nascimento ou adoção de criança com **deficiência permanente decorrente de síndrome congênita associada ao vírus Zika** (art. 473, §2º, da CLT).","A lei também garante **indenização por dano moral** e **pensão especial** a essas pessoas."],"ementa":"Dispõe sobre o direito a indenização por dano moral e a concessão de pensão especial à pessoa com deficiência permanente decorrente de síndrome congênita associada à infecção pelo vírus Zika; e altera a Consolidação das Leis do Trabalho, aprovada pelo Decreto-Lei nº 5.452, de 1º de maio de 1943, e as Leis nºs 8.742, de 7 de dezembro de 1993, e 8.213, de 24 de julho de 1991.","temas":[["trab",8,"Interrupção e suspensão do contrato"]],"em":"2026-11-01"},
 {"id":"l15150","n":"Lei 15.150/2025","nome":"Tatuagem e piercing em cães e gatos é crime","data":"2025-06-16","area":["amb"],"mud":["Quem **realiza ou permite tatuagem ou colocação de piercing em cães e gatos**, com fins estéticos, responde pelas penas de **maus-tratos a animais** (art. 32, §1º-B, da Lei 9.605/1998)."],"ementa":"Altera a Lei nº 9.605, de 12 de fevereiro de 1998, que \"dispõe sobre as sanções penais e administrativas derivadas de condutas e atividades lesivas ao meio ambiente\", para proibir a realização de tatuagens e a colocação de piercings em cães e gatos, com fins estéticos.","temas":[["amb",5,"Responsabilidade ambiental"]],"em":"2026-11-01"},
 {"id":"l15134","n":"Lei 15.134/2025","nome":"Proteção a juízes, promotores e defensores","data":"2025-05-06","area":["penal"],"mud":["O **homicídio** contra membros do **Judiciário, do Ministério Público, da Defensoria Pública, da Advocacia Pública e oficiais de justiça**, no exercício da função ou por causa dela, ou contra seus familiares em razão disso, passou a ser **qualificado** (art. 121, §2º, VII, do CP).","A **lesão corporal dolosa** contra essas pessoas tem a pena aumentada de **1/3 a 2/3** (art. 129, §12).","A lei reconheceu essas funções como **atividade de risco permanente** e garantiu medidas de proteção aos seus membros."],"ementa":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), e as Leis nºs 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos), 12.694, de 24 de julho de 2012, e 13.709, de 14 de agosto de 2018 (Lei Geral de Proteção de Dados Pessoais), para reconhecer como atividade de risco permanente as atribuições inerentes ao Poder Judiciário, ao Ministério Público e à Defensoria Pública e garantir aos seus membros e aos oficiais de justiça medidas de proteção, bem como recrudescer o tratamento penal destinado aos crimes de homicídio e de lesão corporal dolosa contra eles e os membros da Advocacia Pública, desde que no exercício da função ou em decorrência dela, ou contra seu cônjuge, companheiro ou parente, inclusive por afinidade, até o terceiro grau, em razão dessa condição.","temas":[["pen3",2,"Crimes contra a vida"],["pen3",3,"Lesões corporais (art. 129)"]],"em":"2026-11-01"},
 {"id":"l15123","n":"Lei 15.123/2025","nome":"Violência psicológica com deepfake tem pena maior","data":"2025-04-24","area":["penal"],"mud":["No crime de **violência psicológica contra a mulher** (art. 147-B do CP), a pena é **aumentada de metade** se o crime é cometido com **inteligência artificial** ou outro recurso que **altere a imagem ou o som** da vítima, como os _deepfakes_."],"ementa":"Altera o art. 147-B do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para estabelecer causa de aumento de pena no crime de violência psicológica contra a mulher quando praticado com o uso de inteligência artificial ou de qualquer outro recurso tecnológico que altere imagem ou som da vítima.","temas":[["pen3",6,"Crimes contra a liberdade individual"]],"q":["zp05"],"em":"2026-11-01"},
 {"id":"l15109","n":"Lei 15.109/2025","nome":"Advogado não adianta custas para cobrar honorários","data":"2025-03-13","area":["etica","pc"],"mud":["Nas **ações de cobrança e nas execuções ou cumprimentos de sentença de honorários advocatícios**, o advogado não precisa **adiantar as custas**: elas são pagas ao final pelo réu ou executado que deu causa ao processo (art. 82, §3º, do CPC)."],"ementa":"Altera a Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil), para dispensar o advogado do adiantamento de custas processuais em ações de cobrança e em execuções de honorários advocatícios.","temas":[["etica",8,"Honorários advocatícios"],["tgp",8,"Os sujeitos do processo"]],"em":"2026-11-01"},
 {"id":"l15108","n":"Lei 15.108/2025","nome":"Menor sob guarda volta a ser dependente no INSS","data":"2025-03-13","area":["prev","eca"],"mud":["O **menor sob guarda judicial** voltou ao texto da Lei 8.213/1991: como o enteado e o menor sob tutela, **equipara-se a filho**, mediante declaração do segurado e se não tiver condições de se sustentar (art. 16, §2º).","A lei confirmou o que o STF já tinha decidido (ADIs 4.878 e 5.083, 2021): o menor sob guarda tem direito à **pensão por morte** do guardião."],"aa":[["Menor sob guarda no INSS","fora do texto da lei desde 1997 (protegido pelo STF)","equiparado a filho na própria lei"]],"ementa":"Altera o § 2º do art. 16 da Lei nº 8.213, de 24 de julho de 1991, para equiparar ao filho do segurado o menor sob sua guarda judicial, mediante declaração do segurado, desde que o menor não possua condições suficientes para o próprio sustento e educação.","temas":[["prev",3,"Segurados e dependentes"],["eca",4,"Família substituta"]],"q":["pv29","zv02"],"em":"2026-11-01"},
 {"id":"lc214","n":"LC 214/2025","nome":"Reforma tributária: CBS, IBS e Imposto Seletivo","data":"2025-01-16","area":["trib"],"mud":["Regulamentou os tributos criados pela **EC 132/2023**: a **CBS**, federal, que substitui o PIS e a Cofins; o **IBS**, de Estados, DF e Municípios, que substitui o ICMS e o ISS; e o **Imposto Seletivo**, sobre bens e serviços prejudiciais à saúde ou ao meio ambiente.","IBS e CBS formam o **IVA dual**: base ampla, não cumulatividade plena, cobrança no **destino** e cálculo \"por fora\".","**Transição**: 2026 é ano de teste; em 2027 a CBS é cobrada integralmente e acabam o PIS e a Cofins; de 2029 a 2032 o ICMS e o ISS diminuem; em 2033 eles deixam de existir."],"vig":"Durante a transição, os tributos antigos e os novos convivem. Em 2026, ainda se estudam e se cobram ICMS, ISS, PIS e Cofins.","top":1,"ementa":"Institui o Imposto sobre Bens e Serviços (IBS), a Contribuição Social sobre Bens e Serviços (CBS) e o Imposto Seletivo (IS); cria o Comitê Gestor do IBS e altera a legislação tributária.","temas":[["trib",3,"Competência tributária"]],"em":"2026-11-01"},
 {"id":"l15068","n":"Lei 15.068/2024","nome":"Economia solidária vira pessoa jurídica","data":"2024-12-23","area":["civil"],"mud":["Os **empreendimentos de economia solidária** entraram no rol das pessoas jurídicas de direito privado (art. 44, VII, do Código Civil), com aplicação subsidiária das regras das associações (art. 44, §2º).","A lei também criou a Política Nacional e o Sistema Nacional de Economia Solidária (Sinaes)."],"ementa":"Dispõe sobre os empreendimentos de economia solidária e a Política Nacional de Economia Solidária; cria o Sistema Nacional de Economia Solidária (Sinaes); e altera a Lei nº 10.406, de 10 de janeiro de 2002 (Código Civil).","temas":[["civ1",4,"A pessoa jurídica"]],"em":"2026-11-01"},
 {"id":"ec135","n":"EC 135/2024","nome":"Abono salarial, teto e DRU","data":"2024-12-20","area":["prev","adm","fin","const"],"mud":["**Abono salarial (PIS/Pasep)**: continua valendo 1 salário mínimo, mas o **limite de renda** passou a ser 2 salários mínimos de 2025 **corrigidos pelo INPC**, com piso de 1,5 salário mínimo (art. 239, §§3º e 3º-A).","**Teto remuneratório**: as parcelas indenizatórias que ficam fora do teto devem estar em **lei ordinária nacional**; até ela sair, continuam fora as já previstas em lei (art. 37, §11).","**DRU**: até 31/12/2032, ficam desvinculados **30%** da arrecadação da União com contribuições sociais (art. 76 do ADCT).","**Fundeb**: a partir de 2026, pelo menos **4%** dos recursos vão para a criação de **matrículas em tempo integral**."],"aa":[["Limite de renda do abono","2 salários mínimos do ano","2 salários mínimos de 2025, corrigidos pelo INPC (piso de 1,5)"]],"ementa":"Altera os arts. 37, 163, 165, 212-A e 239 da Constituição Federal e o Ato das Disposições Constitucionais Transitórias (ADC T).","temas":[["prev",1,"A seguridade social"],["adm",6,"Agentes públicos"],["fin",6,"Vedações orçamentárias"],["con2",13,"Ordem social"]],"q":["zv01"],"em":"2026-11-01"},
 {"id":"l15040","n":"Lei 15.040/2024","nome":"Marco Legal dos Seguros","data":"2024-12-09","area":["civil"],"mud":["O contrato de seguro saiu do Código Civil: os **arts. 757 a 802 foram revogados**, e as regras agora estão na Lei 15.040/2024.","**Agravamento do risco**: o segurado perde a garantia se agravar o risco **intencionalmente e de forma relevante**, e a seguradora só recusa a indenização se provar o **nexo causal** com o sinistro (arts. 13 a 16).","**Atraso no prêmio**: a mora na 1ª parcela resolve o contrato; nas demais, a garantia só fica suspensa depois de **notificação com prazo de 15 dias**, e a resolução exige pelo menos mais **30 dias** (arts. 20 e 21).","**Suicídio** nos 2 primeiros anos do seguro de vida: o beneficiário não recebe o capital, mas tem direito à **reserva matemática** (art. 120).","**Prescrição**: 1 ano para o segurado, contado da recusa expressa e motivada, e **3 anos** para o beneficiário ou o terceiro prejudicado (art. 126)."],"aa":[["Onde está a regra do seguro","arts. 757 a 802 do Código Civil","Lei 15.040/2024"],["Prescrição do segurado","1 ano (art. 206, §1º, II, do CC)","1 ano da recusa expressa e motivada (art. 126)"]],"vig":"Em vigor desde dezembro de 2025, 1 ano depois da publicação. Questões antigas que citam os arts. 763, 766, 768 e 798 do Código Civil estão desatualizadas.","top":1,"ementa":"Dispõe sobre normas de seguro privado; e revoga dispositivos da Lei nº 10.406, de 10 de janeiro de 2002 (Código Civil), e do Decreto-Lei nº 73, de 21 de novembro de 1966.","temas":[["civ3",8,"Contratos em espécie III: serviços, mandato e outros"],["civ1",10,"Prescrição e decadência"],["civ3",9,"Locação de imóvel urbano (Lei 8.245/1991)"]],"q":["c329","c330"],"em":"2026-11-01"},
 {"id":"l15035","n":"Lei 15.035/2024","nome":"Nome de condenado por crime sexual fica público","data":"2024-11-27","area":["penal"],"mud":["Desde a **condenação em primeira instância** por estupro, estupro de vulnerável, registro não autorizado da intimidade sexual, exploração sexual de vulnerável e crimes ligados à prostituição, o **nome, o CPF e o crime** do condenado ficam públicos na consulta processual, salvo decisão fundamentada do juiz (art. 234-B, §1º, do CP).","O sigilo do processo e das informações da **vítima** continua garantido. A lei também mandou criar o **Cadastro Nacional de Pedófilos e Predadores Sexuais**."],"ementa":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para permitir a consulta pública do nome completo e do número de inscrição no Cadastro de Pessoas Físicas (CPF) das pessoas condenadas por crimes contra a dignidade sexual, garantido o sigilo do processo e das informações relativas à vítima, e a Lei nº 14.069, de 1º de outubro de 2020, para determinar a criação do Cadastro Nacional de Pedófilos e Predadores Sexuais.","temas":[["pen3",8,"Crimes contra a dignidade sexual"]],"q":["zp07"],"em":"2026-11-01"},
 {"id":"l14994","n":"Lei 14.994/2024","nome":"Pacote antifeminicídio","data":"2024-10-09","area":["penal","pp"],"mud":["O **feminicídio** deixou de ser qualificadora do homicídio e virou **crime autônomo** (art. 121-A do CP), com reclusão de **20 a 40 anos**, a maior pena do Código.","Lesão corporal contra a mulher por razões da condição do sexo feminino e lesão na violência doméstica: reclusão de **2 a 5 anos** (art. 129, §§9º e 13). Nos crimes contra a honra nessas condições, a pena é **em dobro** (art. 141, §3º).","**Descumprir medida protetiva** da Lei Maria da Penha: reclusão de **2 a 5 anos** e multa (art. 24-A).","Ao condenado por crime contra a mulher por razões da condição do sexo feminino, a **perda do cargo** e a incapacidade para o poder familiar são **automáticas** (art. 92, §2º, do CP).","Processos de crime hediondo ou de violência contra a mulher têm **prioridade de tramitação** (art. 394-A do CPP)."],"aa":[["Feminicídio","qualificadora do homicídio (12 a 30 anos)","crime autônomo (20 a 40 anos)"]],"top":1,"ementa":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), o Decreto-Lei nº 3.688, de 3 de outubro de 1941 (Lei das Contravenções Penais), a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), a Lei nº 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos), a Lei nº 11.340, de 7 de agosto de 2006 (Lei Maria da Penha) e o Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), para tornar o feminicídio crime autônomo, agravar a sua pena e a de outros crimes praticados contra a mulher por razões da condição do sexo feminino, bem como para estabelecer outras medidas destinadas a prevenir e coibir a violência praticada contra a mulher.","temas":[["pen3",2,"Crimes contra a vida"],["pen3",3,"Lesões corporais (art. 129)"],["pen3",5,"Crimes contra a honra"],["pen2",9,"Efeitos da condenação e reabilitação"],["pen3",11,"Associação criminosa e leis especiais"],["pp2",3,"Procedimentos"]],"q":["pe24"],"em":"2026-11-01"},
 {"id":"ec133","n":"EC 133/2024","nome":"30% dos fundos para candidaturas de pessoas negras","data":"2024-08-22","area":["eleit"],"mud":["Os partidos devem destinar no mínimo **30%** do Fundo Especial de Financiamento de Campanha e do fundo partidário às **candidaturas de pessoas pretas e pardas**.","A cota se soma aos **30%** para as **candidaturas femininas** (EC 117/2022)."],"ementa":"Impõe aos partidos políticos a obrigatoriedade da aplicação de recursos financeiros para candidaturas de pessoas pretas e pardas; estabelece parâmetros e condições para regularização e refinanciamento de débitos de partidos políticos; e reforça a imunidade tributária dos partidos políticos conforme prevista na Constituição Federal.","temas":[["eleit",8,"Propaganda e financiamento"]],"em":"2026-11-01"},
 {"id":"l14939","n":"Lei 14.939/2024","nome":"Feriado local não comprovado pode ser corrigido","data":"2024-07-30","area":["pc"],"mud":["Se o recorrente não comprovar o **feriado local** ao interpor o recurso, o tribunal **manda corrigir o vício** ou o **desconsidera**, se a informação já constar do processo eletrônico (art. 1.003, §6º, do CPC)."],"ementa":"Altera a Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil), para prever que o tribunal determine a correção do vício de não comprovação da ocorrência de feriado local pelo recorrente, ou desconsidere a omissão caso a informação conste do processo eletrônico.","temas":[["pc2",1,"Teoria geral dos recursos"]],"em":"2026-11-01"},
 {"id":"lc208","n":"LC 208/2024","nome":"Protesto da dívida ativa interrompe a prescrição","data":"2024-07-02","area":["trib"],"mud":["O **protesto extrajudicial da certidão de dívida ativa** (o protesto em cartório) passou a **interromper a prescrição** do crédito tributário, ao lado do despacho que ordena a citação na execução fiscal (art. 174 do CTN)."],"ementa":"Altera a Lei nº 4.320, de 17 de março de 1964, para dispor sobre a cessão de direitos creditórios originados de créditos tributários e não tributários dos entes da Federação, e a Lei nº 5.172, de 25 de outubro de 1966 (Código Tributário Nacional), para prever o protesto extrajudicial como causa de interrupção da prescrição e para autorizar a administração tributária a requisitar informações a entidades e órgãos públicos ou privados.","temas":[["trib",7,"Crédito tributário"],["prpub",6,"Prática tributária"]],"q":["xt10"],"em":"2026-11-01"},
 {"id":"l14905","n":"Lei 14.905/2024","nome":"Correção pelo IPCA e juros pela Selic menos o IPCA","data":"2024-06-28","area":["civil","pt"],"mud":["Sem índice combinado nem lei específica, a **correção monetária** segue o **IPCA** (art. 389, parágrafo único, do Código Civil).","Os **juros legais** passaram a ser a **taxa Selic, deduzido o IPCA** (art. 406, §1º). Se o resultado for negativo, a taxa é zero no período (§3º).","No **mútuo para fins econômicos** sem taxa pactuada, vale essa taxa legal (art. 591, parágrafo único).","Na Justiça do Trabalho, o TST aplica o IPCA e a taxa legal a partir de **30/8/2024**."],"ementa":"Altera a Lei nº 10.406, de 10 de janeiro de 2002 (Código Civil), para dispor sobre atualização monetária e juros.","temas":[["civ2",6,"Inadimplemento"],["civ3",7,"Contratos em espécie II: doação e empréstimo"],["prc",3,"A petição inicial"],["prt",6,"A execução trabalhista"]],"q":["c217"],"em":"2026-11-01"},
 {"id":"l14879","n":"Lei 14.879/2024","nome":"Foro de eleição precisa ter ligação com o caso","data":"2024-06-04","area":["pc"],"mud":["A **eleição de foro** só produz efeito se constar de instrumento escrito, se referir a um negócio determinado e **guardar pertinência com o domicílio ou a residência de uma das partes ou com o local da obrigação** (art. 63, §1º, do CPC).","Ajuizar a ação em **juízo aleatório**, sem ligação com as partes ou com o negócio, é **prática abusiva**, e o juiz pode declinar da competência **de ofício** (art. 63, §5º)."],"ementa":"Altera a Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil), para estabelecer que a eleição de foro deve guardar pertinência com o domicílio das partes ou com o local da obrigação e que o ajuizamento de ação em juízo aleatório constitui prática abusiva, passível de declinação de competência de ofício.","temas":[["tgp",7,"Competência"]],"q":["pc12"],"em":"2026-11-01"},
 {"id":"l14843","n":"Lei 14.843/2024","nome":"Saída temporária só para estudar","data":"2024-04-11","area":["penal"],"mud":["A **saída temporária** passou a servir **só para estudar** (curso supletivo profissionalizante, ensino médio ou superior), pelo tempo das aulas. Acabaram a visita à família e as atividades de retorno ao convívio social (art. 122 da LEP).","Quem cumpre pena por crime **hediondo** ou com **violência ou grave ameaça** não tem saída temporária nem **trabalho externo sem vigilância direta** (art. 122, §2º).","A progressão de regime passou a exigir também o **exame criminológico**. Para o STJ, a exigência, mais gravosa, não alcança crimes anteriores à lei."],"aa":[["Para que serve a saída temporária","visitar a família, estudar e atividades de retorno ao convívio","só estudar"],["Quem fica sem saída","só o condenado por hediondo com resultado morte","hediondo ou crime com violência ou grave ameaça"]],"vig":"Conhecida como Lei Sargento PM Dias. O Congresso derrubou o veto à parte da saída temporária em maio de 2024.","ementa":"Altera a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), para dispor sobre a monitoração eletrônica do preso, prever a realização de exame criminológico para progressão de regime e restringir o benefício da saída temporária.","temas":[["pen2",8,"Execução: progressão, remição e detração"],["pen2",2,"Espécies de pena"]],"em":"2026-11-01"},
 {"id":"l14836","n":"Lei 14.836/2024","nome":"Empate favorece o réu e habeas corpus de ofício","data":"2024-04-08","area":["pp"],"mud":["Nos julgamentos penais ou processuais penais em órgão colegiado, **o empate favorece o réu**, proclamado de imediato, ainda que o tribunal esteja incompleto (art. 615, §1º, do CPP).","Qualquer juiz pode conceder **habeas corpus de ofício**, individual ou coletivo, ao ver coação ilegal em qualquer processo, **mesmo sem conhecer a ação ou o recurso** (art. 647-A do CPP)."],"ementa":"Altera a Lei nº 8.038, de 28 de maio de 1990, e o Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), para dispor sobre o resultado de julgamento em matéria penal ou processual penal em órgãos colegiados e sobre a concessão de habeas corpus de ofício.","temas":[["pp2",8,"Ações autônomas de impugnação"],["pp2",7,"Recursos no processo penal"]],"q":["zr03","zr04"],"em":"2026-11-01"},
 {"id":"l14811","n":"Lei 14.811/2024","nome":"Bullying vira crime","data":"2024-01-12","area":["penal"],"mud":["Criou o crime de **intimidação sistemática (bullying)** (art. 146-A do CP): pena de **multa**, se a conduta não constituir crime mais grave.","Pela internet, redes sociais ou jogos on-line, é o **cyberbullying**: reclusão de **2 a 4 anos** e multa (art. 146-A, parágrafo único).","No induzimento, instigação ou auxílio a suicídio ou automutilação, a pena é **aplicada em dobro** se o autor lidera, coordena ou administra o grupo, a comunidade ou a rede virtual (art. 122, §5º)."],"ementa":"Institui medidas de proteção à criança e ao adolescente contra a violência nos estabelecimentos educacionais ou similares, prevê a Política Nacional de Prevenção e Combate ao Abuso e Exploração Sexual da Criança e do Adolescente e altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), e as Leis nºs 8.072, de 25 de julho de 1990 (Lei dos Crimes Hediondos), e 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente).","temas":[["pen3",6,"Crimes contra a liberdade individual"],["pen3",2,"Crimes contra a vida"]],"q":["zp03"],"em":"2026-11-01"}
];
